<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('SUBSCRIPTION_VIEW_OWN');$errors=[];$subs=SubscriptionEligibilityService::ownSubscriptions();$current=$subs['current'];$pending=$subs['pending'];$scheduled=$subs['scheduled'];$plans=SubscriptionEligibilityService::plans();$prices=['GOLD'=>35000,'PREMIUM'=>55000,'PLATINUM'=>100500];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$id=SubscriptionEligibilityService::request((int)$_POST['plan_version_id'],(int)Auth::user()['id']);header('Location: '.Url::to('carrier/subscription-payment.php?id='.$id));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Carrier Subscription';require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><span class="eyebrow dark">Fleet growth plans</span><h1>Carrier subscription</h1><p>Choose a first plan or select the plan that should follow your current subscription.</p></div><span class="badge">Premium fleet access</span></div><?php if(isset($_GET['payment'])):?><div class="success">Bank transfer details submitted. Operations will verify the payment.</div><?php endif;foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?>
<?php if($current):?><section class="card feature-card subscription-current"><div><span class="status-pill status-active">Current plan</span><h2><?=h($current['plan_name'])?> plan</h2><p class="plan-price">TSh <?=h(number_format((float)($prices[$current['plan_code']]??0),0))?></p></div><dl class="definition"><dt>Truck limit</dt><dd><?=h($current['max_trucks']??'Unlimited')?></dd><dt>Driver limit</dt><dd><?=h($current['max_drivers']??'Unlimited')?></dd><dt>Start</dt><dd class="timestamp"><?=h($current['start_at'])?></dd><dt>End</dt><dd class="timestamp"><?=h($current['end_at'])?></dd></dl></section><?php endif;?>
<?php if($pending):?><section class="card" style="margin-top:18px"><span class="status-pill status-requested">Awaiting payment verification</span><h2><?=h($pending['plan_name'])?> — future selection</h2><p>You may change this selection below until Operations confirms the payment.</p><a class="button secondary" href="<?=h(Url::to('carrier/subscription-payment.php?id='.$pending['subscription_id']))?>">Enter or update bank transfer details</a></section><?php endif;?>
<?php if($scheduled):?><section class="card" style="margin-top:18px"><span class="status-pill status-confirmed">Scheduled future plan</span><h2><?=h($scheduled['plan_name'])?></h2><p>Starts <strong class="timestamp"><?=h($scheduled['start_at'])?></strong> after the current subscription ends.</p></section><?php endif;?>
<h2 style="margin-top:26px"><?=$current?'Choose a future plan':'Choose a plan'?></h2><div class="plan-grid"><?php foreach($plans as$p):$code=strtoupper($p['plan_code']);$selected=$pending&&(int)$pending['plan_version_id']===(int)$p['subscription_plan_version_id'];?><form method="post" class="plan-card plan-<?=h(strtolower($code))?>"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="plan_version_id" value="<?=h($p['subscription_plan_version_id'])?>"><span class="plan-kicker"><?=h($code)?></span><h2><?=h($p['plan_name'])?></h2><p class="plan-price">TSh <?=h(number_format((float)($prices[$code]??0),0))?></p><p class="muted">Pilot subscription rate</p><ul class="plan-features"><li><?=h($p['max_trucks']??'Unlimited')?> trucks</li><li><?=h($p['max_drivers']??'Unlimited')?> drivers</li><li>Compliance and eligibility monitoring</li></ul><button class="button"><?=$selected?'Continue payment details':($pending?'Change future plan':($current?'Select future plan':'Choose '.$p['plan_name']))?></button></form><?php endforeach;?></div><p class="field-help">Changing an unpaid selection replaces that pending request. A paid future plan must be changed through Operations.</p><?php require BASE_PATH.'/app/Views/layout/footer.php';
